 // never overflow int64.
 extern "C" void scan_and_histogram(const int64_t* in, int64_t* out, size_t n, uint64_t* hist) {
     for (int b = 0; b < 256; ++b) hist[b] = 0;
+    // Use sub-histograms to break store-to-load dependencies on hot bins.
+    // uint32_t is sufficient since n <= 20M and n/16 < 2^32.
+    // The [256][16] layout ensures that for a hot bin b, the 16 sub-bins
+    // are contiguous in memory, favoring write-combining.
+    uint32_t sub_hist[256][16] = {0};
     int64_t sum = 0;
     for (size_t i = 0; i < n; ++i) {
         sum += in[i];
         out[i] = sum;
-        hist[in[i] & 255]++;
+        sub_hist[in[i] & 255][i & 15]++;
+    }
+    for (int b = 0; b < 256; ++b) {
+        uint64_t total = 0;
+        for (int k = 0; k < 16; ++k) {
+            total += sub_hist[b][k];
+        }
+        hist[b] = total;
     }
 }
